package org.example.server.quotation;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/quotations") public class QuotationController{private final QuotationService s;public QuotationController(QuotationService s){this.s=s;}@GetMapping public List<QuotationDtos.QuoteDto> list(){return s.list();}@GetMapping("/page")public QuotationDtos.Page page(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="25")int size,@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="")String number,@RequestParam(defaultValue="")String customer,@RequestParam(defaultValue="")String status,@RequestParam(defaultValue="")String from,@RequestParam(defaultValue="")String to,@RequestParam(defaultValue="")String valid,@RequestParam(defaultValue="")String salesperson,@RequestParam(defaultValue="")String minAmount,@RequestParam(defaultValue="")String maxAmount,@RequestParam(defaultValue="")String followUp,@RequestParam(defaultValue="")String source){return s.page(page,size,q,number,customer,status,from,to,valid,salesperson,minAmount,maxAmount,followUp,source);}@GetMapping("/{id}")public QuotationDtos.QuoteDto quote(@PathVariable int id){return s.quote(id);}@GetMapping("/{id}/lines")public List<QuotationDtos.LineDto> lines(@PathVariable int id){return s.lines(id);}@GetMapping("/sources")public List<String> sources(){return s.sourceChoices();}@GetMapping("/items/search")public List<QuotationDtos.ItemChoiceDto> itemChoices(@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="12")int limit){return s.itemChoices(q,limit);}@PostMapping public QuotationDtos.QuoteDto save(@RequestBody QuotationDtos.SaveRequest d){return s.save(d);}@PutMapping("/{id}")public QuotationDtos.QuoteDto update(@PathVariable int id,@RequestBody QuotationDtos.SaveRequest d){return s.save(new QuotationDtos.SaveRequest(id,d.date(),d.valid(),d.customerId(),d.subtotal(),d.discountAmount(),d.gstAmount(),d.total(),d.remarks(),d.followUp(),d.salesperson(),d.source(),d.createdBy(),d.lines()));}@PutMapping("/{id}/notes")public QuotationDtos.Ok notes(@PathVariable int id,@RequestBody QuotationDtos.Text d){s.notes(id,d.value());return ok();}@PostMapping("/{id}/sent")public QuotationDtos.Ok sent(@PathVariable int id,@RequestParam String channel){s.markSent(id,channel);return ok();}@PostMapping("/{id}/follow-up")public QuotationDtos.Ok follow(@PathVariable int id,@RequestBody QuotationDtos.FollowUp d){s.followUp(id,d);return ok();}@PostMapping("/{id}/convert")public QuotationDtos.Text convert(@PathVariable int id,@RequestParam(defaultValue="System")String user){return new QuotationDtos.Text(s.convert(id,user));}@PostMapping("/{id}/duplicate")public QuotationDtos.Text duplicate(@PathVariable int id,@RequestParam(defaultValue="System")String user){return new QuotationDtos.Text(s.duplicate(id,user));}@DeleteMapping("/{id}")public QuotationDtos.Ok delete(@PathVariable int id){s.delete(id);return ok();}private QuotationDtos.Ok ok(){return new QuotationDtos.Ok(true,"OK");}}
